from ortools.sat.python import cp_model
import json

# Input data
X = -1
game_data = [
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

# Create model
model = cp_model.CpModel()
rows = len(game_data)
cols = len(game_data[0]) if rows > 0 else 0

# Create variables for X cells (mines)
mines = []
for i in range(rows):
    row_vars = []
    for j in range(cols):
        if game_data[i][j] == X:
            row_vars.append(model.NewBoolVar(f'mine_{i}_{j}'))
        else:
            row_vars.append(None)  # Placeholder for non-X cells
    mines.append(row_vars)

# Add constraints based on numbered cells
for i in range(rows):
    for j in range(cols):
        cell_value = game_data[i][j]
        if cell_value != X:
            adjacent_vars = []
            # Check all 8 adjacent cells
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    if di == 0 and dj == 0:
                        continue  # Skip current cell
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols:
                        if mines[ni][nj] is not None:
                            adjacent_vars.append(mines[ni][nj])
            # Add sum constraint for adjacent mines
            model.Add(sum(adjacent_vars) == cell_value)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Prepare solution output
solution = {'mines': []}
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    for i in range(rows):
        row = []
        for j in range(cols):
            if game_data[i][j] == X:
                row.append(solver.Value(mines[i][j]) == 1)
            else:
                row.append(False)
        solution['mines'].append(row)
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
