from ortools.sat.python import cp_model
import json

n_teams = 8
weeks = 2 * (n_teams - 1)
periods = n_teams // 2

model = cp_model.CpModel()

home = []
away = []
for w in range(weeks):
    current_home = []
    current_away = []
    for p in range(periods):
        current_home.append(model.NewIntVar(0, n_teams-1, f'home_{w}_{p}'))
        current_away.append(model.NewIntVar(0, n_teams-1, f'away_{w}_{p}'))
    home.append(current_home)
    away.append(current_away)

for w in range(weeks):
    for p in range(periods):
        model.Add(home[w][p] != away[w][p])

for w in range(weeks):
    all_teams = []
    for p in range(periods):
        all_teams.append(home[w][p])
        all_teams.append(away[w][p])
    model.AddAllDifferent(all_teams)

for p in range(periods):
    for t in range(n_teams):
        occurrences = []
        for w in range(weeks):
            h = home[w][p]
            occurs_home = model.NewBoolVar(f'occurs_h_{p}_{t}_{w}')
            model.Add(h == t).OnlyEnforceIf(occurs_home)
            model.Add(h != t).OnlyEnforceIf(occurs_home.Not())
            occurrences.append(occurs_home)
            a = away[w][p]
            occurs_away = model.NewBoolVar(f'occurs_a_{p}_{t}_{w}')
            model.Add(a == t).OnlyEnforceIf(occurs_away)
            model.Add(a != t).OnlyEnforceIf(occurs_away.Not())
            occurrences.append(occurs_away)
        model.Add(sum(occurrences) <= 2)

for i in range(n_teams):
    for j in range(n_teams):
        if i != j:
            pair_vars = []
            for w in range(weeks):
                for p in range(periods):
                    var = model.NewBoolVar(f'pair_{i}_{j}_{w}_{p}')
                    model.AddBoolAnd([home[w][p] == i, away[w][p] == j]).OnlyEnforceIf(var)
                    model.AddBoolOr([home[w][p] != i, away[w][p] != j]).OnlyEnforceIf(var.Not())
                    pair_vars.append(var)
            model.Add(sum(pair_vars) == 1)

solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'home': [[solver.Value(home[w][p]) for p in range(periods)] for w in range(weeks)],
        'away': [[solver.Value(away[w][p]) for p in range(periods)] for w in range(weeks)]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
